-- v63 -> v64: renamed and removed reason and event codes (refactor RF-006b).
-- Generated from docs/refactor/reason_code_proposals.py and the v63 schema; see
-- docs/refactor/REASON_CODE_AUDIT.md. Every stored code is rewritten, history
-- included, so the code knows only the new codes. Codes inside JSON are rewritten
-- where they are a whole JSON string value ("OLD" -> "NEW"). incoming_events.raw_body
-- (what external senders sent) is not touched.
PRAGMA foreign_keys=OFF;
BEGIN IMMEDIATE;
CREATE TEMP TABLE nextgen_v64_guard(ok INTEGER CHECK(ok=1));
INSERT OR ROLLBACK INTO nextgen_v64_guard SELECT user_version=63 FROM pragma_user_version;

-- batch_torrent_submissions: its CHECK constraint names codes, so the table is rebuilt.
CREATE TABLE batch_torrent_submissions_v64 (
 plan_id INTEGER PRIMARY KEY REFERENCES "batch_user_evaluation_plans"(plan_id),
 reservation_job_id INTEGER NOT NULL REFERENCES jobs(job_id),
 first_job_id INTEGER NOT NULL REFERENCES jobs(job_id),
 first_attempt INTEGER NOT NULL CHECK(first_attempt>0),
 info_hash TEXT NOT NULL UNIQUE CHECK(length(info_hash)=40 AND info_hash NOT GLOB '*[^a-f0-9]*'),
 info_sha256 TEXT CHECK(length(info_sha256)=64 AND info_sha256 NOT GLOB '*[^a-f0-9]*'),
 ownership_marker TEXT NOT NULL UNIQUE CHECK(length(ownership_marker)=32 AND ownership_marker NOT GLOB '*[^a-f0-9]*'),
 base_url TEXT NOT NULL CHECK(length(base_url) BETWEEN 1 AND 2048),
 save_path TEXT NOT NULL CHECK(length(save_path) BETWEEN 2 AND 4096),
 category TEXT NOT NULL CHECK(length(category) BETWEEN 1 AND 64),
 timeout_seconds INTEGER NOT NULL CHECK(timeout_seconds BETWEEN 1 AND 60),
 api_major INTEGER NOT NULL CHECK(api_major IN (4,5)),
 fingerprint TEXT NOT NULL UNIQUE CHECK(length(fingerprint)=64 AND fingerprint NOT GLOB '*[^a-f0-9]*'),
 configuration_revision INTEGER NOT NULL CHECK(configuration_revision>0),
 state TEXT NOT NULL CHECK(state IN ('UNCERTAIN','EXTERNAL','REVIEW','OWNED_STOPPED')),
 reason_code TEXT NOT NULL CHECK(
   (state='UNCERTAIN' AND reason_code='TORRENT_SUBMISSION_UNCERTAIN') OR
   (state='EXTERNAL' AND reason_code='TORRENT_ALREADY_PRESENT') OR
   (state='REVIEW' AND reason_code='TORRENT_OWNERSHIP_CONFLICT') OR
   (state='OWNED_STOPPED' AND reason_code='TORRENT_STOPPED_CONFIRMED')),
 created_at_ms INTEGER NOT NULL CHECK(created_at_ms>=0),
 updated_at_ms INTEGER NOT NULL CHECK(updated_at_ms>=created_at_ms)
);
INSERT INTO batch_torrent_submissions_v64(plan_id, reservation_job_id, first_job_id, first_attempt, info_hash, info_sha256, ownership_marker, base_url, save_path, category, timeout_seconds, api_major, fingerprint, configuration_revision, state, reason_code, created_at_ms, updated_at_ms)
SELECT plan_id, reservation_job_id, first_job_id, first_attempt, info_hash, info_sha256, ownership_marker, base_url, save_path, category, timeout_seconds, api_major, fingerprint, configuration_revision, state, CASE reason_code
  WHEN 'BATCH_SELECTION_CONFLICT' THEN 'SEASON_PACK_SELECTION_CONFLICT'
  WHEN 'JELLYFIN_REFRESH_REVIEW' THEN 'MEDIA_SERVER_REFRESH_REVIEW'
  WHEN 'KEEP_NOT_READY' THEN 'KEEP_IMPORT_REVIEW'
  WHEN 'PROWLARR_RELEASE_WITHDRAWN' THEN 'RELEASE_WITHDRAWN'
  WHEN 'PROWLARR_SEARCH_TIMEOUT' THEN 'RELEASE_SEARCH_TIMEOUT'
  WHEN 'SHOKO_METADATA_REVIEW' THEN 'METADATA_ENRICHMENT_REVIEW'
  WHEN 'SONARR_BACKFILL_PLAN_CONFLICT' THEN 'EPISODE_DISCOVERY_PLAN_CONFLICT'
  WHEN 'SONARR_CANDIDATES_EXHAUSTED' THEN 'RELEASE_CANDIDATES_EXHAUSTED'
  WHEN 'SONARR_DISCOVERY_AUTH_FAILED' THEN 'EPISODE_DISCOVERY_OUTDATED'
  WHEN 'SONARR_DISCOVERY_CONFIGURATION_INVALID' THEN 'EPISODE_DISCOVERY_OUTDATED'
  WHEN 'SONARR_DISCOVERY_EPISODE_NOT_FOUND' THEN 'EPISODE_DISCOVERY_OUTDATED'
  WHEN 'SONARR_DISCOVERY_NO_RESULTS' THEN 'EPISODE_DISCOVERY_OUTDATED'
  WHEN 'SONARR_DISCOVERY_REVIEW' THEN 'EPISODE_DISCOVERY_OUTDATED'
  WHEN 'SONARR_DISCOVERY_TIMEOUT' THEN 'EPISODE_DISCOVERY_OUTDATED'
  WHEN 'SONARR_DISCOVERY_UNAVAILABLE' THEN 'EPISODE_DISCOVERY_OUTDATED'
  WHEN 'SONARR_DISCOVERY_UNSUPPORTED' THEN 'EPISODE_DISCOVERY_OUTDATED'
  WHEN 'SONARR_EPISODES_NOT_LISTED' THEN 'EPISODE_DISCOVERY_OUTDATED'
  WHEN 'SONARR_SELECTION_CONFLICT' THEN 'RELEASE_SELECTION_CONFLICT'
  WHEN 'TORRENT_PROVENANCE_CONFLICT' THEN 'TORRENT_OWNERSHIP_CONFLICT'
  WHEN 'TRIAL_COUNTS_INVALID' THEN 'USER_EVALUATION_COUNTS_INVALID'
  WHEN 'TRIAL_DISABLED' THEN 'USER_EVALUATION_DISABLED'
  WHEN 'TRIAL_OUTSIDE_WINDOW' THEN 'USER_EVALUATION_OUTSIDE_WINDOW'
  WHEN 'TRIAL_PLAN_CONFLICT' THEN 'USER_EVALUATION_PLAN_CONFLICT'
  WHEN 'TRIAL_SELECTED' THEN 'USER_EVALUATION_SELECTED'
  ELSE reason_code END, created_at_ms, updated_at_ms
FROM batch_torrent_submissions;
DROP TABLE batch_torrent_submissions;
ALTER TABLE batch_torrent_submissions_v64 RENAME TO batch_torrent_submissions;
CREATE INDEX idx_batch_submission_job ON batch_torrent_submissions(reservation_job_id);

